/**
 * Render an inline SVG icon. Unknown names fall back to a neutral circle so a typo never breaks a page.
 */
function icon(string $name, string $class = 'w-5 h-5', array $attrs = []): string
{
    $paths = icon_paths();
    $inner = $paths[$name] ?? $paths['circle'];
    $extra = '';
    foreach ($attrs as $k => $v) {
        $extra .= ' ' . htmlspecialchars((string) $k, ENT_QUOTES) . '="' . htmlspecialchars((string) $v, ENT_QUOTES) . '"';
    }
    return '<svg xmlns="http://www.w3.org/2000/svg" class="' . htmlspecialchars($class, ENT_QUOTES) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"' . $extra . '>' . $inner . '</svg>';
}

/** All icon names (used by the icon picker in the CMS). */
function icon_names(): array
{
    return array_keys(icon_paths());
}
